import{_ as t,c as o,o as d,ae as a}from"./chunks/framework.Cd-3tpCq.js";const u=JSON.parse('{"title":"Product","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/graphql-api/shop/product/index.md","filePath":"api/graphql-api/shop/product/index.md"}'),r={name:"api/graphql-api/shop/product/index.md"};function i(c,e,s,n,l,p){return d(),o("div",null,e[0]||(e[0]=[a('<h1 id="product" tabindex="-1">Product <a class="header-anchor" href="#product" aria-label="Permalink to &quot;Product&quot;">​</a></h1><p>The Product menu is the storefront catalog. It powers three screens: a product-listing page, a search results page, and a product-detail page. Everything here is public read access — no customer login is needed to browse.</p><h2 id="listing-and-searching" tabindex="-1">Listing and searching <a class="header-anchor" href="#listing-and-searching" aria-label="Permalink to &quot;Listing and searching&quot;">​</a></h2><p>One field, <code>products</code>, backs both the listing page and the search page:</p><ul><li><strong>Listing</strong> — call <code>products</code> with pagination and sorting. It returns the catalog page by page.</li><li><strong>Searching</strong> — add the <code>query</code> argument. The same field now matches that keyword against the catalog and returns the hits.</li></ul><p>Because a single field serves both, the two screens receive an identical product shape and can share the same rendering code. Results are cursor-paginated, so a listing walks forward with <code>first</code> + <code>after</code> rather than page numbers.</p><p>See <a href="/api/graphql-api/shop/queries/get-products.html">List Products</a> and <a href="/api/graphql-api/shop/queries/search-products.html">Search Products</a>.</p><h2 id="viewing-one-product" tabindex="-1">Viewing one product <a class="header-anchor" href="#viewing-one-product" aria-label="Permalink to &quot;Viewing one product&quot;">​</a></h2><p>The <code>product</code> field returns one product&#39;s full detail and accepts three different lookups:</p><ul><li><code>id</code> — the product&#39;s identifier, IRI or numeric.</li><li><code>sku</code> — the stock-keeping unit.</li><li><code>urlKey</code> — the storefront slug, e.g. <code>blossom-breeze-cotton-printed-short-skirt</code>.</li></ul><p>A storefront route built on a slug can therefore call <code>product(urlKey: …)</code> directly, with no separate step to turn the slug into an ID first.</p><p>See <a href="/api/graphql-api/shop/queries/get-product.html">Single Product</a>.</p><h2 id="filtering-and-sorting" tabindex="-1">Filtering and sorting <a class="header-anchor" href="#filtering-and-sorting" aria-label="Permalink to &quot;Filtering and sorting&quot;">​</a></h2><p>Filters are passed to <code>products</code> as a JSON string in the <code>filter</code> argument. The accepted keys are:</p><table tabindex="0"><thead><tr><th>Key</th><th>Filters by</th></tr></thead><tbody><tr><td><code>type</code></td><td>Product type — one of the seven listed below.</td></tr><tr><td><code>sku</code></td><td>An exact SKU.</td></tr><tr><td><code>category_id</code></td><td>Membership of one category.</td></tr><tr><td><code>price_from</code> / <code>price_to</code></td><td>A price range, inclusive on both ends.</td></tr><tr><td><code>new</code> / <code>featured</code></td><td>The &quot;new&quot; and &quot;featured&quot; merchandising flags.</td></tr><tr><td><code>&lt;attribute_code&gt;</code></td><td>Any filterable attribute, e.g. <code>color</code>, <code>size</code>, <code>brand</code>. The value is the option ID; comma-separate several.</td></tr></tbody></table><p>Supplying more than one key narrows the result — the keys combine, they do not widen the set. Sorting is separate from filtering: <code>sortKey</code> accepts <code>ID</code> (the default), <code>TITLE</code>, <code>PRICE</code>, <code>CREATED_AT</code>, and <code>UPDATED_AT</code>, and <code>reverse: true</code> flips the direction.</p><p>Full syntax, argument list, and worked examples are on <a href="/api/graphql-api/shop/queries/get-products.html">List Products</a>.</p><h2 id="product-types" tabindex="-1">Product types <a class="header-anchor" href="#product-types" aria-label="Permalink to &quot;Product types&quot;">​</a></h2><p>The catalog carries seven product types. A single-product response is type-aware: the blocks that apply to that type are populated and the rest are absent.</p><table tabindex="0"><thead><tr><th>Type</th><th>What it is</th><th>Type-specific fields</th></tr></thead><tbody><tr><td>Simple</td><td>One sellable item with its own price and stock.</td><td><code>price</code>, <code>specialPrice</code>, <code>images</code>, <code>attributeValues</code></td></tr><tr><td>Configurable</td><td>A parent whose variants are chosen by attribute, e.g. size and colour.</td><td><code>variants</code>, <code>combinations</code>, <code>superAttributeOptions</code></td></tr><tr><td>Grouped</td><td>A set of associated products presented and bought from one page.</td><td><code>groupedProducts</code> → <code>associatedProduct</code></td></tr><tr><td>Bundle</td><td>A kit the shopper assembles by picking from each bundle option.</td><td><code>bundleOptions</code> → <code>bundleOptionProducts</code> → <code>product</code></td></tr><tr><td>Virtual</td><td>A non-shippable item such as a service or membership.</td><td><code>price</code>, <code>specialPrice</code>, <code>attributeValues</code></td></tr><tr><td>Downloadable</td><td>A digital product delivered as files, with optional free samples.</td><td><code>downloadableLinks</code>, <code>downloadableSamples</code></td></tr><tr><td>Booking</td><td>An item reserved against a date and time slot.</td><td><code>bookingProducts</code></td></tr></tbody></table><p>Filter the listing to one type with <code>filter: &quot;{\\&quot;type\\&quot;: \\&quot;configurable\\&quot;}&quot;</code>. Each type&#39;s fields are documented with examples on <a href="/api/graphql-api/shop/queries/get-products.html">List Products</a>.</p><h2 id="booking-slots" tabindex="-1">Booking slots <a class="header-anchor" href="#booking-slots" aria-label="Permalink to &quot;Booking slots&quot;">​</a></h2><p>Booking products are the one type that needs a second call before add-to-cart. The <code>bookingSlots</code> field takes a product ID and a date and returns the slots a shopper can actually reserve on that date, which is what the date-picker on a booking product page renders.</p><p>See <a href="/api/graphql-api/shop/queries/get-booking-slots.html">Booking Slots</a>.</p><h2 id="currency-and-locale" tabindex="-1">Currency and locale <a class="header-anchor" href="#currency-and-locale" aria-label="Permalink to &quot;Currency and locale&quot;">​</a></h2><p>Two optional request headers change what the catalog returns:</p><ul><li><code>X-Currency</code> — prices are converted to that currency, and the <code>formatted*</code> price fields carry its symbol.</li><li><code>X-Locale</code> — names, descriptions, and attribute values are returned in that language.</li></ul><p>Both fall back to the current channel&#39;s defaults when omitted or when the value is not enabled on the channel.</p><h2 id="operations" tabindex="-1">Operations <a class="header-anchor" href="#operations" aria-label="Permalink to &quot;Operations&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operation</th><th>GraphQL field</th><th>Description</th></tr></thead><tbody><tr><td>List &amp; filter products</td><td><a href="/api/graphql-api/shop/queries/get-products.html"><code>products</code></a></td><td>Paginated catalog with sorting and category / type / price / attribute filters.</td></tr><tr><td>Search products</td><td><a href="/api/graphql-api/shop/queries/search-products.html"><code>products</code></a></td><td>The same field driven by its <code>query</code> argument — a keyword search across the catalog.</td></tr><tr><td>View one product</td><td><a href="/api/graphql-api/shop/queries/get-product.html"><code>product</code></a></td><td>Full type-aware detail for a single product, looked up by <code>id</code>, <code>sku</code>, or <code>urlKey</code>.</td></tr><tr><td>List booking slots</td><td><a href="/api/graphql-api/shop/queries/get-booking-slots.html"><code>bookingSlots</code></a></td><td>Bookable slots for one booking-type product on a given date.</td></tr></tbody></table><p>These are public read endpoints — they require the storefront key header. A customer Bearer token is optional.</p>',31)]))}const g=t(r,[["render",i]]);export{u as __pageData,g as default};
